const connection = msg.payload;
const clients    = Object.values(connection.clients);
const target     = clients.find(c => c.client_system === "wasos");
const source     = clients.find(c => c.client_system !== "wasos");

msg.topic    = source.client_system;
msg.metadata = {
    source:     source,
    target:     target,
    connection_name: connection.name
};

return msg;

return {
    _msgid: msg._msgid,
    topic: "new_message",
    entry: {
        id:        msg.payload.id,
        text:      msg.payload.text,
        timestamp: msg.payload.timestamp,
        author:    msg.payload.author,
        files:     msg.payload.files,
        labels:    msg.payload.labels,
        metadata:  msg.metadata
    }
};

// Normal entry fra Prune msg — msg.entry finnes
if (msg.entry) {
    const connName = msg.entry.metadata.connection_name;
    const connections = global.get('parat_bridge.connections') || {};
    const conn = connections[connName];

    if (conn && conn._initial_count !== undefined) {
        conn._initial_delivered = (conn._initial_delivered || 0) + 1;

        if (conn._initial_delivered >= conn._initial_count) {
            node.send([msg, null]);

            const clientList = Object.values(conn.clients);
            const now = Date.now();

            clientList.forEach((client, idx) => {
                const otherNames = clientList
                    .filter(c => c.identifier !== client.identifier)
                    .map(c => c.name)
                    .join(' og ');

                node.send([null, {
                    topic: 'new_message',
                    entry: {
                        id: 'pb-err-' + (now + idx) + '-connected-' + Math.random().toString(36).slice(2, 5),
                        text: '✅ Tilkobling etablert. Du er nå koblet til ' + otherNames + '. Meldinger kan sendes begge veier.',
                        timestamp: now + idx,
                        author: 'System-melding',
                        files: [],
                        labels: [],
                        metadata: {
                            source: { client_system: 'parat_bridge', name: 'parat_bridge', identifier: 'parat_bridge' },
                            target: client,
                            connection_name: connName
                        }
                    }
                }]);
            });

            delete conn._initial_count;
            delete conn._initial_delivered;
            global.set('parat_bridge.connections.' + connName, conn);
            return null;
        }

        global.set('parat_bridge.connections.' + connName, conn);
    }

    return [msg, null];
}

// Tom array-tilfelle — msg.metadata fra switch output 2
const connName = msg.metadata && msg.metadata.connection_name;
const connections = global.get('parat_bridge.connections') || {};
const conn = connections[connName];

if (conn && connName) {
    const clientList = Object.values(conn.clients);
    const now = Date.now();

    clientList.forEach((client, idx) => {
        const otherNames = clientList
            .filter(c => c.identifier !== client.identifier)
            .map(c => c.name)
            .join(' og ');

        node.send([null, {
            topic: 'new_message',
            entry: {
                id: 'pb-err-' + (now + idx) + '-connected-' + Math.random().toString(36).slice(2, 5),
                text: '✅ Tilkobling etablert. Du er nå koblet til ' + otherNames + '. Meldinger kan sendes begge veier.',
                timestamp: now + idx,
                author: 'System-melding',
                files: [],
                labels: [],
                metadata: {
                    source: { client_system: 'parat_bridge', name: 'parat_bridge', identifier: 'parat_bridge' },
                    target: client,
                    connection_name: connName
                }
            }
        }]);
    });
}

return null;

const connName = msg.metadata.connection_name;
const connections = global.get('parat_bridge.connections') || {};
const conn = connections[connName];
if (conn) {
    conn._initial_count = msg.payload.length;
    conn._initial_delivered = 0;
    global.set('parat_bridge.connections.' + connName, conn);
}
return msg;
